"use client";

import * as React from "react";
import { Menubar as MenubarPrimitive } from "@base-ui/react/menubar";
import { Menu as MenuPrimitive } from "@base-ui/react/menu";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { focusRing, menuItemBase, popoverSurface, popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

type PositionerProps = Pick<
  MenuPrimitive.Positioner.Props,
  "align" | "alignOffset" | "side" | "sideOffset"
>;

/** The menu panel: the white floating panel, at least 12rem wide, padded 0.375rem. */
const menuPanel = cn(
  popoverSurface,
  popupMotion,
  "min-w-48 max-h-(--available-height) overflow-y-auto p-1.5",
);

/** One menu in the bar: its trigger and its panel. */
const MenubarMenu = MenuPrimitive.Root;

/** Groups related rows, and gives a label something to name. */
const MenubarGroup = MenuPrimitive.Group;

/** Moves a menu panel to the end of the document body. */
const MenubarPortal = MenuPrimitive.Portal;

/** Wraps a nested menu: its sub-trigger and its sub-content. */
const MenubarSub = MenuPrimitive.SubmenuRoot;

/** Holds a set of radio rows where only one can be chosen. */
const MenubarRadioGroup = MenuPrimitive.RadioGroup;

/**
 * Bold retail menubar: a plain row of menu names on the white page, the way
 * a store header lists its departments. No track and no frame.
 */
const Menubar = React.forwardRef<
  HTMLDivElement,
  WithClassName<MenubarPrimitive.Props>
>(({ className, ...props }, ref) => (
  <MenubarPrimitive
    ref={ref}
    data-slot="menubar"
    className={cn(
      "inline-flex h-10 items-center gap-1 bg-background text-foreground",
      className,
    )}
    {...props}
  />
));
Menubar.displayName = "Menubar";

/** A menu name in the bar: a medium label that sits on a soft grey pill while its menu is open. */
const MenubarTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<MenuPrimitive.Trigger.Props>
>(({ className, ...props }, ref) => (
  <MenuPrimitive.Trigger
    ref={ref}
    data-slot="menubar-trigger"
    className={cn(
      "inline-flex h-9 cursor-default select-none items-center rounded-full px-4 text-sm font-medium text-foreground",
      "transition-colors duration-fast ease-out",
      "hover:bg-secondary",
      focusRing,
      "data-[popup-open]:bg-secondary",
      "data-[disabled]:pointer-events-none data-[disabled]:text-(--foreground-disabled)",
      className,
    )}
    {...props}
  />
));
MenubarTrigger.displayName = "MenubarTrigger";

/** The panel under a menu name. It drops from the start edge of its trigger. */
const MenubarContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<MenuPrimitive.Popup.Props> & PositionerProps
>(
  (
    {
      className,
      align = "start",
      alignOffset = 0,
      side,
      sideOffset = 8,
      ...props
    },
    ref,
  ) => (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          ref={ref}
          data-slot="menubar-content"
          className={cn(menuPanel, className)}
          {...props}
        />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  ),
);
MenubarContent.displayName = "MenubarContent";

/** A nested menu panel. It opens beside its row, level with the row's top. */
const MenubarSubContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<MenuPrimitive.Popup.Props> & PositionerProps
>(
  (
    {
      className,
      align = "start",
      alignOffset = -6,
      side = "right",
      sideOffset = 4,
      ...props
    },
    ref,
  ) => (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          ref={ref}
          data-slot="menubar-sub-content"
          className={cn(menuPanel, className)}
          {...props}
        />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  ),
);
MenubarSubContent.displayName = "MenubarSubContent";

/** A row that opens a nested menu, with a right chevron at the end. */
const MenubarSubTrigger = React.forwardRef<
  HTMLElement,
  WithClassName<MenuPrimitive.SubmenuTrigger.Props> & {
    inset?: boolean;
  }
>(({ className, inset, children, ...props }, ref) => (
  <MenuPrimitive.SubmenuTrigger
    ref={ref}
    data-slot="menubar-sub-trigger"
    className={cn(
      menuItemBase,
      "data-[popup-open]:bg-accent data-[popup-open]:text-accent-foreground",
      inset && "ps-9",
      className,
    )}
    {...props}
  >
    {children}
    <Icon
      icon="mingcute:right-line"
      className="ms-auto size-4 text-muted-foreground rtl:rotate-180"
      aria-hidden="true"
    />
  </MenuPrimitive.SubmenuTrigger>
));
MenubarSubTrigger.displayName = "MenubarSubTrigger";

/**
 * A menu row on the soft grey highlight. The destructive row keeps red text
 * and fills with the pale red tint, the one place red appears in a menu.
 */
const MenubarItem = React.forwardRef<
  HTMLElement,
  WithClassName<MenuPrimitive.Item.Props> & {
    inset?: boolean;
    variant?: "default" | "destructive";
  }
>(({ className, inset, variant = "default", ...props }, ref) => (
  <MenuPrimitive.Item
    ref={ref}
    data-slot="menubar-item"
    data-variant={variant}
    className={cn(
      menuItemBase,
      "[&_svg]:size-4 [&_svg]:shrink-0",
      variant === "destructive" &&
        "text-(--destructive-text) data-[highlighted]:bg-(--destructive-tint) data-[highlighted]:text-(--destructive-text)",
      inset && "ps-9",
      className,
    )}
    {...props}
  />
));
MenubarItem.displayName = "MenubarItem";

/** A row that toggles on and off. A black tick sits at the end when on. */
const MenubarCheckboxItem = React.forwardRef<
  HTMLElement,
  WithClassName<MenuPrimitive.CheckboxItem.Props>
>(({ className, children, ...props }, ref) => (
  <MenuPrimitive.CheckboxItem
    ref={ref}
    data-slot="menubar-checkbox-item"
    className={cn(menuItemBase, "pe-9", className)}
    {...props}
  >
    {children}
    <span className="pointer-events-none absolute end-3 flex size-4 items-center justify-center">
      <MenuPrimitive.CheckboxItemIndicator>
        <Icon icon="mingcute:check-line" className="size-4" aria-hidden="true" />
      </MenuPrimitive.CheckboxItemIndicator>
    </span>
  </MenuPrimitive.CheckboxItem>
));
MenubarCheckboxItem.displayName = "MenubarCheckboxItem";

/** One choice in a radio group. A small black dot sits at the end when chosen. */
const MenubarRadioItem = React.forwardRef<
  HTMLElement,
  WithClassName<MenuPrimitive.RadioItem.Props>
>(({ className, children, ...props }, ref) => (
  <MenuPrimitive.RadioItem
    ref={ref}
    data-slot="menubar-radio-item"
    className={cn(menuItemBase, "pe-9", className)}
    {...props}
  >
    {children}
    <span className="pointer-events-none absolute end-3 flex size-4 items-center justify-center">
      <MenuPrimitive.RadioItemIndicator>
        <span className="block size-2 rounded-full bg-foreground" />
      </MenuPrimitive.RadioItemIndicator>
    </span>
  </MenuPrimitive.RadioItem>
));
MenubarRadioItem.displayName = "MenubarRadioItem";

/** A small muted heading over a group of rows. Use it inside a group. */
const MenubarLabel = React.forwardRef<
  HTMLDivElement,
  WithClassName<MenuPrimitive.GroupLabel.Props> & {
    inset?: boolean;
  }
>(({ className, inset, ...props }, ref) => (
  <MenuPrimitive.GroupLabel
    ref={ref}
    data-slot="menubar-label"
    className={cn(
      "px-3 py-1.5 text-xs font-medium text-muted-foreground",
      inset && "ps-9",
      className,
    )}
    {...props}
  />
));
MenubarLabel.displayName = "MenubarLabel";

/** The hairline between groups, running to the panel's edges. */
const MenubarSeparator = React.forwardRef<
  HTMLDivElement,
  WithClassName<MenuPrimitive.Separator.Props>
>(({ className, ...props }, ref) => (
  <MenuPrimitive.Separator
    ref={ref}
    data-slot="menubar-separator"
    className={cn("-mx-1.5 my-1.5 h-px bg-border", className)}
    {...props}
  />
));
MenubarSeparator.displayName = "MenubarSeparator";

/** The keyboard shortcut at the end of a row, in small muted type. */
const MenubarShortcut = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) => (
  <span
    data-slot="menubar-shortcut"
    className={cn("ml-auto ps-4 text-xs text-muted-foreground", className)}
    {...props}
  />
);
MenubarShortcut.displayName = "MenubarShortcut";

export {
  Menubar,
  MenubarMenu,
  MenubarTrigger,
  MenubarContent,
  MenubarItem,
  MenubarSeparator,
  MenubarLabel,
  MenubarCheckboxItem,
  MenubarRadioGroup,
  MenubarRadioItem,
  MenubarPortal,
  MenubarSubContent,
  MenubarSubTrigger,
  MenubarGroup,
  MenubarSub,
  MenubarShortcut,
};
